shell_commands:
node -e "
const fs = require('fs');
const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
pkg.version = '0.4.0';
pkg.dependencies = {
  '@types/express': pkg.dependencies['@types/express'],
  '@types/node': pkg.dependencies['@types/node'],
  '@types/ws': pkg.dependencies['@types/ws'],
  'ajv': '^6.15.0',
  'cookie': pkg.dependencies['cookie'],
  'cookie-parser': pkg.dependencies['cookie-parser'],
  'cors': pkg.dependencies['cors'],
  'express': pkg.dependencies['express'],
  'uuid': pkg.dependencies['uuid'],
  'ws': pkg.dependencies['ws']
};
fs.writeFileSync('package.json', JSON.stringify(pkg, null, 2) + '\n');
"

node -e "
const fs = require('fs');
const lock = JSON.parse(fs.readFileSync('package-lock.json', 'utf8'));
lock.version = '0.4.0';
lock.packages[''].version = '0.4.0';
const deps = lock.packages[''].dependencies;
lock.packages[''].dependencies = {
  '@types/express': deps['@types/express'],
  '@types/node': deps['@types/node'],
  '@types/ws': deps['@types/ws'],
  'ajv': '^6.15.0',
  'cookie': deps['cookie'],
  'cookie-parser': deps['cookie-parser'],
  'cors': deps['cors'],
  'express': deps['express'],
  'uuid': deps['uuid'],
  'ws': deps['ws']
};
fs.writeFileSync('package-lock.json', JSON.stringify(lock, null, 2) + '\n');
"
